<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';import {useApplication} from '../../application';import {useMaterials,useKnowledgeMaterials} from './useMaterials';import KnowledgeMaterialPicker from './KnowledgeMaterialPicker.vue';import Icon from '../../shared/Icon.vue';
const props=defineProps<{meetingId:string;locked?:boolean}>();const emit=defineEmits<{state:[value:{busy:boolean;blocked:boolean;failed:boolean;hasFiles:boolean}]}>();const {session,materials:api,journals}=useApplication();const actor=()=>session.current.value?.actor.enterpriseId??null;const material=useMaterials(api,actor,()=>props.meetingId,journals,()=>!props.locked);const picker=useKnowledgeMaterials(api,actor,()=>props.meetingId,journals);const fileInput=ref<HTMLInputElement>(),pickerOpen=ref(false);const state=computed(()=>material.state.value);watch(state,value=>emit('state',value),{immediate:true});
function chooseLocal(){if(!props.locked)fileInput.value?.click();}async function selected(event:Event){const drop=event as DragEvent;const input=event.target as HTMLInputElement|null;const files=[...(drop.dataTransfer?.files??input?.files??[])];if(input)input.value='';if(files.length)await material.addLocal(files);}async function confirmKnowledge(documents:readonly any[]){try{await material.addKnowledge(documents);pickerOpen.value=false;picker.close();}catch{} }function openPicker(){if(!props.locked)pickerOpen.value=true;}function remove(id:string){void material.remove(id);}function retry(id:string){void material.retry(id);}function retryJob(id:string){void material.retryJob(id);}defineExpose({reload:material.reload,ensureReady:material.ensureReady});onUnmounted(()=>{material.dispose();picker.dispose();});
</script>
<template><section class="aci-import-section material-import-section"><div class="ac-material-heading"><h3>会议背景材料及相关文档</h3><div class="flex wrap"><button type="button" class="btn" :disabled="locked||state.busy" @click="chooseLocal">上传本地文件</button><button type="button" class="btn" :disabled="locked||state.busy" @click="openPicker">从知识库选择</button></div></div><div class="small muted mb12">补充材料有助于更精准理解会议内容和生成纪要；未添加时，将基于会议录音或转写内容处理。</div><div data-aci-files="material"><div v-for="job in material.jobs.value" :key="job.id" class="file-item ac-file material-job"><div class="f-ico"><Icon name="file" :size="20"/></div><div class="ac-file-main"><div class="f-name" :title="job.name">{{job.name}}</div><div class="f-meta">{{job.kind==='KNOWLEDGE'?'知识库引用':'本地文件'}} · {{job.status}}</div><div v-if="job.error" class="ac-error small mt8" role="alert">{{job.error}}</div></div><div class="flex wrap"><button v-if="job.needsFile" type="button" class="btn sm" @click="chooseLocal">重新选择原文件</button><button v-if="job.error&&!job.needsFile" type="button" class="btn sm" @click="retryJob(job.id)">重试</button><button v-if="job.canRemove" type="button" class="btn sm ghost" @click="material.removeJob(job.id)">移除</button></div></div><div v-for="item in material.items.value" :key="item.id" class="file-item ac-file"><div class="f-ico"><Icon :name="item.source==='KNOWLEDGE'?'layers':'file'" :size="20"/></div><div class="ac-file-main"><div class="f-name" :title="item.name">{{item.name}}</div><div class="f-meta">{{item.name.split('.').pop()?.toUpperCase()}} · {{item.source==='KNOWLEDGE'?'知识库引用 · '+(item.sourceVersion?.slice(0,12)??'版本未知'):'本地文件'}} · {{item.sizeBytesToken}} B</div><div v-if="item.error" class="ac-error small mt8" role="alert">{{item.error}}</div></div><div class="flex wrap"><button v-if="item.state==='FAILED'" type="button" class="btn sm" @click="retry(item.id)">重试解析</button><button type="button" class="btn sm ghost" @click="remove(item.id)">移除</button></div></div></div><div class="upload-zone ac-material-drop" :class="{'has-files':material.items.value.length||material.jobs.value.length}" role="button" tabindex="0" @click="chooseLocal" @keydown.enter.prevent="chooseLocal" @keydown.space.prevent="chooseLocal" @dragover.prevent @drop.prevent="selected"><span v-if="material.items.value.length||material.jobs.value.length">继续拖入背景材料，也可从知识库选择</span><span v-else>可拖入背景材料，也可从知识库选择；无材料可直接开始处理。</span></div><input ref="fileInput" hidden multiple type="file" aria-label="选择背景材料" accept=".pdf,.pptx,.docx" @change="selected"/><div v-if="material.error.value" class="aci-import-error ac-error" role="alert">{{material.error.value}}</div><div v-if="material.listing.value?.materialsPending" class="small ac-error mt8" role="status">材料仍在解析，解析完成后才会进入处理上下文。</div></section><KnowledgeMaterialPicker :open="pickerOpen" :picker="picker" :busy="state.busy" @close="pickerOpen=false" @confirm="confirmKnowledge"/></template>
